SELECT * FROM t FOR VERSION AS OF 8954597067493422955;

SELECT * FROM t FOR VERSION AS OF 'historical-tag';

SELECT * FROM t FOR TIMESTAMP AS OF TIMESTAMP '2022-03-23 09:59:29.803 Europe/Vienna';

SELECT * FROM t FOR TIMESTAMP AS OF CURRENT_TIMESTAMP - INTERVAL '1' DAY;

